import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const casesDirectory = fileURLToPath(new URL("../target/cases/", import.meta.url));
const caseIds = ["alpha", "beta", "gamma"];

await mkdir(casesDirectory, { recursive: true });

for (const caseId of caseIds) {
  await writeFile(
    join(casesDirectory, `${caseId}.json`),
    `${JSON.stringify({ case: caseId })}\n`,
  );
}

